#include "NexumFxProcessor.h"
using namespace juce;
namespace noctrl {
bool NexumFxProcessor::isBusesLayoutSupported(const BusesLayout& buses)const{auto input=buses.getMainInputChannelSet(),output=buses.getMainOutputChannelSet();return input==output&&(output==AudioChannelSet::mono()||output==AudioChannelSet::stereo());}
void NexumFxProcessor::prepareToPlay(double rate,int block){SynthProcessor::prepareToPlay(rate,block);work.setSize(2,8192);work.clear();globalMix.reset(rate,.02);globalMix.setCurrentAndTargetValue(value("fxMix"));outputGain.reset(rate,.02);outputGain.setCurrentAndTargetValue(Decibels::decibelsToGain(value("fxOutput")));wasBypassed=false;}
void NexumFxProcessor::updateMeters(const AudioBuffer<float>& audio){float decay=std::exp(-(float)audio.getNumSamples()/(float)(sampleRate*.35));for(int c=0;c<2;++c){float peak=audio.getNumChannels()>0?audio.getMagnitude(jmin(c,audio.getNumChannels()-1),0,audio.getNumSamples()):0;masterMeters[c].store(jmax(peak,masterMeters[c].load()*decay));}meter.store(jmax(masterMeters[0].load(),masterMeters[1].load()));}
void NexumFxProcessor::processBlockBypassed(AudioBuffer<float>& audio,MidiBuffer& midi){midi.clear();if(!wasBypassed)if(auto runtime=std::atomic_load(&fxRuntime))runtime->reset();wasBypassed=true;updateMeters(audio);}
void NexumFxProcessor::processBlock(AudioBuffer<float>& audio,MidiBuffer& midi){ScopedNoDenormals guard;midi.clear();if(value("fxBypass")>.5f){processBlockBypassed(audio,midi);return;}wasBypassed=false;if(audio.getNumChannels()==0)return;double bpm=120;if(auto* head=getPlayHead())if(auto pos=head->getPosition())if(auto hostTempo=pos->getBpm())if(std::isfinite(*hostTempo))bpm=jlimit(20.,400.,*hostTempo);double beat=std::numeric_limits<double>::quiet_NaN();if(auto* head=getPlayHead())if(auto pos=head->getPosition())if(pos->getIsPlaying())if(auto ppq=pos->getPpqPosition())if(std::isfinite(*ppq))beat=*ppq;tempo.store(bpm);auto runtime=std::atomic_load(&fxRuntime);int chunk=macros()->links.empty()?8192:64;for(int start=0;start<audio.getNumSamples();start+=chunk){int n=jmin(chunk,audio.getNumSamples()-start);for(int c=0;c<2;++c)work.copyFrom(c,0,audio,jmin(c,audio.getNumChannels()-1),start,n);updateSettings(n);globalMix.setTargetValue(dspValue("fxMix"));outputGain.setTargetValue(Decibels::decibelsToGain(dspValue("fxOutput")));if(runtime)runtime->process(0,work,0,n,effectiveParameters,bpm,beat+start/sampleRate*bpm/60.);for(int i=0;i<n;++i){float gain=outputGain.getNextValue(),mix=globalMix.getNextValue();for(int c=0;c<jmin(2,audio.getNumChannels());++c){float dry=audio.getSample(c,start+i);float sample=(mix>=1.f?work.getSample(c,i):mix<=0.f?dry:dry+(work.getSample(c,i)-dry)*mix)*gain;audio.setSample(c,start+i,std::isfinite(sample)?sample:0.f);}}}updateMeters(audio);}
double NexumFxProcessor::getTailLengthSeconds()const{double tail=0;for(auto& entry:rack()->entries){if(value(fxId(entry.slot,"enabled"))<.5f)continue;if(entry.type==4){auto& controls=fxDefinitions()[4].controls;double time=controls[0].from(value(fxId(entry.slot,"p0")))*.001,feedback=controls[1].from(value(fxId(entry.slot,"p1")));int sync=roundToInt(controls[5].from(value(fxId(entry.slot,"p5"))));if(sync>0){double beats[]={0,.25,.5,1,2,4,8};time=jmin(2.19,beats[jlimit(1,6,sync)]*60/tempo.load());}tail+=time*(feedback>.0001?std::ceil(std::log(.00001)/std::log(feedback)):1);}else if(entry.type==11)tail+=30;else if(entry.type==3)tail+=4.2;else if(entry.type==1||entry.type==8||entry.type==9||entry.type==10)tail+=1;}return jmin(600.,tail);}
void NexumFxProcessor::getStateInformation(MemoryBlock& data){auto tree=state.copyState();for(auto name:{"FxRack","MacroRouting","LiveModRouting"}){auto old=tree.getChildWithName(name);if(old.isValid())tree.removeChild(old,nullptr);}tree.addChild(rack()->save(),-1,nullptr);tree.addChild(macros()->save(),-1,nullptr);tree.addChild(liveMods()->save(),-1,nullptr);tree.setProperty("version",1,nullptr);if(auto xml=tree.createXml())copyXmlToBinary(*xml,data);}
void NexumFxProcessor::setStateInformation(const void* data,int size){if(size<=0||size>256*1024*1024)return;auto xml=getXmlFromBinary(data,size);if(!xml||!xml->hasTagName("NEXUM_FX"))return;auto tree=ValueTree::fromXml(*xml);for(auto* base:getParameters())if(auto* parameter=dynamic_cast<RangedAudioParameter*>(base)){auto node=tree.getChildWithProperty("id",parameter->getParameterID());if(!node.isValid()){node=ValueTree("PARAM");node.setProperty("id",parameter->getParameterID(),nullptr);node.setProperty("value",parameter->convertFrom0to1(parameter->getDefaultValue()),nullptr);tree.addChild(node,-1,nullptr);}else if(!std::isfinite((double)node.getProperty("value",0)))return;}const ScopedLock callbackLock(getCallbackLock());state.replaceState(tree);restoreMacros(tree.getChildWithName("MacroRouting"));restoreLiveMods(tree.getChildWithName("LiveModRouting"));restoreFxRack(tree.getChildWithName("FxRack"));outputGain.setCurrentAndTargetValue(Decibels::decibelsToGain(value("fxOutput")));globalMix.setCurrentAndTargetValue(value("fxMix"));wasBypassed=false;updateSettings();}
}

